const tickets = $input.all();

if (tickets.length === 0 || !tickets[0].json.folio) {
  return { 
    mensaje: "📂 No tienes tickets pendientes de cierre asignados a tu usuario. ¡Buen trabajo! ✅"
  };
}

let msg = "📂 *TUS TICKETS PENDIENTES*\n";
msg += "------------------------------------\n";

tickets.forEach(t => {
  const fecha = new Date(t.json.fecha_solicitud).toLocaleDateString('es-HN');
  msg += "📌 *" + t.json.folio + "*\n";
  msg += "📝 " + (t.json.solicitud_descripcion || 'Sin descripción').substring(0, 60) + "...\n";
  msg += "📅 " + fecha + "\n\n";
});

msg += "------------------------------------\n";
msg += "_Escribe el *Folio* para cerrarlo o *menu* para volver._";

return { mensaje: msg };
